"use client"

import * as React from "react"
import * as PopoverPrimitive from "@radix-ui/react-popover"
import { CalendarIcon, XIcon } from "lucide-react"
import type { DateRange } from "react-day-picker"

import { cn } from "@/lib/utils"
import { Calendar, type CalendarEra } from "@/registry/mintel/ui/calendar"

/** Formats a date for display in Thai. Uses the Buddhist Era (BE) calendar by default. */
function formatThaiDate(date: Date, era: CalendarEra = "buddhist", style: "medium" | "long" = "medium") {
  const locale = era === "buddhist" ? "th-TH-u-ca-buddhist" : "th-TH-u-ca-gregory"
  return new Intl.DateTimeFormat(locale, { dateStyle: style }).format(date)
}

const triggerClass =
  "flex h-9 w-full items-center gap-2 rounded-md border border-input bg-transparent px-3 text-left text-sm shadow-xs outline-none transition-[color,box-shadow] " +
  "focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 dark:bg-input/30 dark:hover:bg-input/50 " +
  "aria-invalid:border-destructive aria-invalid:ring-destructive/20"

const contentClass =
  "z-50 max-h-(--radix-popover-content-available-height) w-auto origin-(--radix-popover-content-transform-origin) overflow-y-auto overscroll-contain rounded-xl border bg-popover p-0 text-popover-foreground shadow-lg shadow-brand/5 " +
  "data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95 motion-reduce:animate-none"

type CommonProps = {
  era?: CalendarEra
  placeholder?: string
  className?: string
  disabled?: boolean
  /** Show month/year dropdowns (good for birth dates). */
  dropdowns?: boolean
  fromYear?: number
  toYear?: number
  "aria-invalid"?: boolean
}

function ClearButton({ onClear }: { onClear: () => void }) {
  return (
    <span
      role="button"
      tabIndex={-1}
      aria-label="ล้างวันที่"
      onPointerDown={(e) => {
        e.preventDefault()
        e.stopPropagation()
        onClear()
      }}
      className="ml-auto rounded-full p-0.5 text-muted-foreground hover:bg-accent hover:text-foreground"
    >
      <XIcon className="size-3.5" />
    </span>
  )
}

// Rendered only while the popover is open, so `new Date()` never runs during server prerender
// (Next.js cacheComponents rejects reading the current time there).
function SingleCalendar({
  era,
  value,
  dropdowns,
  fromYear,
  toYear,
  onSelect,
}: {
  era: CalendarEra
  value?: Date
  dropdowns?: boolean
  fromYear?: number
  toYear?: number
  onSelect: (d: Date | undefined) => void
}) {
  const thisYear = new Date().getFullYear()
  return (
    <Calendar
      mode="single"
      era={era}
      selected={value}
      defaultMonth={value}
      captionLayout={dropdowns ? "dropdown" : "label"}
      startMonth={new Date(fromYear ?? thisYear - 100, 0)}
      endMonth={new Date(toYear ?? thisYear + 10, 11)}
      onSelect={onSelect}
    />
  )
}

/** Single date picker. Displays the date in Thai with a BE year (e.g. 19 Nov 2569 BE); `value` is a normal JS Date. */
function DatePicker({
  value,
  onValueChange,
  era = "buddhist",
  placeholder = "เลือกวันที่",
  className,
  disabled,
  dropdowns,
  fromYear,
  toYear,
  ...rest
}: CommonProps & { value?: Date; onValueChange?: (date: Date | undefined) => void }) {
  const [open, setOpen] = React.useState(false)
  return (
    <PopoverPrimitive.Root open={open} onOpenChange={setOpen}>
      <PopoverPrimitive.Trigger
        data-slot="date-picker-trigger"
        disabled={disabled}
        aria-invalid={rest["aria-invalid"]}
        className={cn(triggerClass, className)}
      >
        <CalendarIcon className="size-4 shrink-0 text-muted-foreground" />
        <span className={cn("truncate", !value && "text-muted-foreground")}>
          {value ? formatThaiDate(value, era) : placeholder}
        </span>
        {value && <ClearButton onClear={() => onValueChange?.(undefined)} />}
      </PopoverPrimitive.Trigger>
      <PopoverPrimitive.Portal>
        <PopoverPrimitive.Content align="start" sideOffset={6} className={contentClass}>
          <SingleCalendar
            era={era}
            value={value}
            dropdowns={dropdowns}
            fromYear={fromYear}
            toYear={toYear}
            onSelect={(d) => {
              onValueChange?.(d)
              if (d) setOpen(false)
            }}
          />
        </PopoverPrimitive.Content>
      </PopoverPrimitive.Portal>
    </PopoverPrimitive.Root>
  )
}

// One month on phones, two side by side from `sm` up. Mounted only while open (no SSR mismatch).
function RangeCalendar({
  era,
  value,
  onSelect,
}: {
  era: CalendarEra
  value?: DateRange
  onSelect?: (range: DateRange | undefined) => void
}) {
  const [months] = React.useState(() => (window.matchMedia("(min-width: 640px)").matches ? 2 : 1))
  return (
    <Calendar mode="range" era={era} selected={value} defaultMonth={value?.from} numberOfMonths={months} onSelect={onSelect} />
  )
}

/** Date range picker (two months on desktop, one on phones). */
function DateRangePicker({
  value,
  onValueChange,
  era = "buddhist",
  placeholder = "เลือกช่วงวันที่",
  className,
  disabled,
  ...rest
}: CommonProps & { value?: DateRange; onValueChange?: (range: DateRange | undefined) => void }) {
  const label = value?.from
    ? value.to
      ? `${formatThaiDate(value.from, era)} – ${formatThaiDate(value.to, era)}`
      : formatThaiDate(value.from, era)
    : placeholder
  return (
    <PopoverPrimitive.Root>
      <PopoverPrimitive.Trigger
        data-slot="date-range-picker-trigger"
        disabled={disabled}
        aria-invalid={rest["aria-invalid"]}
        className={cn(triggerClass, className)}
      >
        <CalendarIcon className="size-4 shrink-0 text-muted-foreground" />
        <span className={cn("truncate", !value?.from && "text-muted-foreground")}>{label}</span>
        {value?.from && <ClearButton onClear={() => onValueChange?.(undefined)} />}
      </PopoverPrimitive.Trigger>
      <PopoverPrimitive.Portal>
        <PopoverPrimitive.Content align="start" sideOffset={6} className={contentClass}>
          <RangeCalendar era={era} value={value} onSelect={onValueChange} />
        </PopoverPrimitive.Content>
      </PopoverPrimitive.Portal>
    </PopoverPrimitive.Root>
  )
}

export { DatePicker, DateRangePicker, formatThaiDate }

"use client"

import * as React from "react"
import { ChevronLeftIcon, ChevronRightIcon } from "lucide-react"
import { DayPicker, getDefaultClassNames, type DayPickerProps } from "react-day-picker"
import { th } from "react-day-picker/locale"

import { cn } from "@/lib/utils"

export type CalendarEra = "buddhist" | "gregorian"

const yearOf = (d: Date, era: CalendarEra) => d.getFullYear() + (era === "buddhist" ? 543 : 0)

/**
 * Calendar in Thai by default, with Buddhist Era (BE) years in the caption and year dropdown.
 * Pass `era="gregorian"` for Common Era (CE) years, or any react-day-picker `locale` for other languages.
 * Dates you receive are normal JS Dates (Gregorian) — the era only changes what is displayed.
 */
function Calendar({
  className,
  classNames,
  showOutsideDays = true,
  captionLayout = "label",
  era = "buddhist",
  locale = th,
  formatters,
  ...props
}: DayPickerProps & { era?: CalendarEra }) {
  const d = getDefaultClassNames()
  const monthName = (date: Date) =>
    new Intl.DateTimeFormat(locale?.code ?? "th", { month: "long" }).format(date)
  const monthShort = (date: Date) =>
    new Intl.DateTimeFormat(locale?.code ?? "th", { month: "short" }).format(date)

  return (
    <DayPicker
      showOutsideDays={showOutsideDays}
      captionLayout={captionLayout}
      locale={locale}
      className={cn("bg-background p-3 [--cell-size:--spacing(9)] pointer-coarse:[--cell-size:--spacing(11)]", className)}
      formatters={{
        formatCaption: (date) => `${monthName(date)} ${yearOf(date, era)}`,
        formatYearDropdown: (date) => String(yearOf(date, era)),
        formatMonthDropdown: (date) => monthShort(date),
        ...formatters,
      }}
      classNames={{
        root: cn("w-fit", d.root),
        months: cn("relative flex flex-col gap-4 md:flex-row", d.months),
        month: cn("flex w-full flex-col gap-4", d.month),
        nav: cn("absolute inset-x-0 top-0 flex w-full items-center justify-between gap-1", d.nav),
        button_previous: cn(
          "inline-flex size-(--cell-size) items-center justify-center rounded-md p-0 select-none hover:bg-accent hover:text-accent-foreground aria-disabled:opacity-50",
          d.button_previous
        ),
        button_next: cn(
          "inline-flex size-(--cell-size) items-center justify-center rounded-md p-0 select-none hover:bg-accent hover:text-accent-foreground aria-disabled:opacity-50",
          d.button_next
        ),
        month_caption: cn("flex h-(--cell-size) w-full items-center justify-center px-(--cell-size)", d.month_caption),
        dropdowns: cn("flex h-(--cell-size) w-full items-center justify-center gap-1.5 text-sm font-medium", d.dropdowns),
        dropdown_root: cn(
          "relative rounded-md border border-input shadow-xs has-focus:border-ring has-focus:ring-[3px] has-focus:ring-ring/50",
          d.dropdown_root
        ),
        dropdown: cn("absolute inset-0 bg-popover opacity-0", d.dropdown),
        caption_label: cn(
          "font-heading font-semibold select-none",
          captionLayout === "label"
            ? "text-sm"
            : "flex h-8 items-center gap-1 rounded-md pr-1 pl-2 text-sm [&>svg]:size-3.5 [&>svg]:text-muted-foreground",
          d.caption_label
        ),
        month_grid: "w-full border-collapse",
        weekdays: cn("flex", d.weekdays),
        weekday: cn("flex-1 rounded-md text-[0.8rem] font-normal text-muted-foreground select-none", d.weekday),
        week: cn("mt-2 flex w-full", d.week),
        day: cn(
          "group/day relative aspect-square h-full w-full p-0 text-center select-none [&:first-child[data-selected=true]_button]:rounded-l-md [&:last-child[data-selected=true]_button]:rounded-r-md",
          d.day
        ),
        range_start: cn("rounded-l-md bg-accent", d.range_start),
        range_middle: cn("rounded-none", d.range_middle),
        range_end: cn("rounded-r-md bg-accent", d.range_end),
        today: cn("rounded-md bg-accent text-accent-foreground data-[selected=true]:rounded-none", d.today),
        outside: cn("text-muted-foreground aria-selected:text-muted-foreground", d.outside),
        disabled: cn("text-muted-foreground opacity-50", d.disabled),
        hidden: cn("invisible", d.hidden),
        ...classNames,
      }}
      components={{
        Chevron: ({ orientation, className, ...p }) =>
          orientation === "left" ? (
            <ChevronLeftIcon className={cn("size-4", className)} {...p} />
          ) : (
            <ChevronRightIcon className={cn("size-4", className)} {...p} />
          ),
        DayButton: CalendarDayButton,
      }}
      {...props}
    />
  )
}

function CalendarDayButton({
  className,
  day,
  modifiers,
  ...props
}: React.ComponentProps<"button"> & { day: { date: Date }; modifiers: Record<string, boolean> }) {
  const ref = React.useRef<HTMLButtonElement>(null)
  React.useEffect(() => {
    if (modifiers.focused) ref.current?.focus()
  }, [modifiers.focused])

  return (
    <button
      ref={ref}
      type="button"
      data-day={day.date.toLocaleDateString()}
      data-selected-single={modifiers.selected && !modifiers.range_start && !modifiers.range_end && !modifiers.range_middle}
      data-range-start={modifiers.range_start}
      data-range-end={modifiers.range_end}
      data-range-middle={modifiers.range_middle}
      className={cn(
        "flex aspect-square size-auto w-full min-w-(--cell-size) items-center justify-center rounded-md text-sm leading-none font-normal outline-none",
        "transition-[background-color,transform] duration-300 ease-spring-snappy hover:bg-accent hover:text-accent-foreground active:scale-90 motion-reduce:transition-none",
        "group-data-[focused=true]/day:ring-[3px] group-data-[focused=true]/day:ring-ring/50",
        "data-[selected-single=true]:bg-primary data-[selected-single=true]:font-semibold data-[selected-single=true]:text-primary-foreground",
        "data-[range-start=true]:rounded-md data-[range-start=true]:bg-primary data-[range-start=true]:text-primary-foreground",
        "data-[range-end=true]:rounded-md data-[range-end=true]:bg-primary data-[range-end=true]:text-primary-foreground",
        "data-[range-middle=true]:rounded-none data-[range-middle=true]:bg-accent data-[range-middle=true]:text-accent-foreground",
        className
      )}
      {...props}
    />
  )
}

export { Calendar, CalendarDayButton }
